return [{
  json: {
    source: 'webform',
    requester_email: $json.body.requester_email,
    requester_name: $json.body.requester_name,
    subject: $json.body.subject,
    body_raw: $json.body.body_raw,
    received_at: new Date().toISOString()
  }
}];

const crypto = require('crypto');

const day = new Date().toISOString().slice(0, 10);

const raw = `${$json.requester_email}|${$json.subject}|${day}`;

const hash = crypto
  .createHash('sha256')
  .update(raw)
  .digest('hex');

return [{
  json: {
    ...$json,
    dedup_hash: hash
  }
}];

