const raw = $json.choices[0].message.content;

const parsed = JSON.parse(raw);

// Hard rule: billing and angry tickets always require human review
if (
  ['billing'].includes(parsed.category) ||
  parsed.sentiment === 'angry'
) {
  parsed.risk_flag = true;
}

return [
  {
    json: parsed
  }
];

const ticketId = $('Insert rows in a table').first().json.id;

const points = $json.result.points;

return points.map((p, i) => ({
  json: {
    ticket_id: ticketId,
    rank: i,
    source_doc_id: p.payload.source_doc_id,
    source_type: p.payload.source_type,
    similarity_score: p.score,
    chunk_text: p.payload.chunk_text
  }
}));

const points = $json.result.points;

const contextText = points
  .map(
    p =>
      `[${p.payload.source_type} | score=${p.score.toFixed(3)}] ${p.payload.chunk_text}`
  )
  .join('\n\n');

return [
  {
    json: {
      context_text: contextText,
      citations: points.map(p => p.payload.source_doc_id)
    }
  }
];

